Ext.define('BNK.view.HumanResource.hrd.HrdCrsInfo02MViewController', {
    extend: 'BaseViewController',
    alias: 'controller.HrdCrsInfo02MViewController',

    config: {
        aprHistId: null,
        record: null,
        command: null,
        parentView: null,
        viewId: 'HrdCrsInfo02M'
    },

    onComplete: function() {
        var me = this,
            vm = me.getViewModel(),
            refs = me.getReferences();

        var win = Ext.create('ExpNteAply51M'); // 결과 완료 팝업

        var sumScreen = win.getReferences().sumScreen;
        var message = win.getReferences().message;
        sumScreen.setVisibility(false);
        message.setHtml("연수 취소신청을 완료 하였습니다");
        me.mon(win, 'destroy', function() {
            var me = this,
                //home = Ext.getCmp(Property.ROUTE_HOME),
                home = this.getView().up(Property.ROUTE_HOME),
                naviView = home.lookup('NaviView'),
                backButton = naviView.getNavigationBar().getBackButton();
            me.getParentView().controller.onBtnSearchTap();
            backButton.onTap();	// 뒤로가기
        }, me);

        win.show();
    },

    /* 결재선 버튼 클릭 이벤트 */
    onBtnAplyLineTap: function(button, e, eOpts) {
        var me = this,
            vm = me.getViewModel(),
            refs = me.getReferences(),
            win = Ext.create('BNK.view.common.ApprovalLinePopup', {});

        me.mon(win, 'selected', function(data, popup) {
            popup.close();

            vm.set('applyLine', data);
            var me = this,
                refs = me.getReferences(),
                approvalLineGrid = refs.approvalLineGrid;

            ApprovalBoxSvc.setApprovalLine({
                scope               : me,
                command             : Constants.sanction.DRAFT, // 결재선구분자 : 기안(01)
                approvalLineGrid    : approvalLineGrid,   // 결재선 그리드 객체
                approvalLineRecords : data        // 결재선선택 데이터
            });

        }, me);


        win.show();
    },

    /* 결재 버튼 클릭 이벤트 */
    onBtnAplyTap: function(button, e, eOpts) {
        var me = this,
            vm = me.getViewModel(),
            refs = me.getReferences(),
            grid = refs.detailGrid,
            approvalLineGrid = refs.approvalLineGrid,
            record = vm.data.detail;		//연수과정신청 데이터

            //VALIDATION AREA 20190322/20190322
            // 결재선
            if(!vm.get('applyLine')){
                Ext.Msg.alert('확인', '- 결재선을 선택해주세요');
            return;
        }
        //END VALIDATION AREA


        //GO SANCTION POPUP	 (신청)
        ApprovalBoxSvc.draft({
            scope                 : me,
            edocCd                : vm.get('docCd'),				 	 		// 전자문서관리에서 설정된 문서코드: 화면ID를 사용함
            docNm                 : vm.get('docNm'), 							 		// 문서명
            bizDvcd               : 'HRD', 							 		// 업무구분코드
            bizServiceId          : 'HrdCrsSvc.saveHrdCrsInfo',   			// 연관 업무서비스ID
            aprHistId             : me.getAprHistId(),						 	 		// 결재이력ID
            approvalLineRecords   : approvalLineGrid.getJsonAllRecords(), 	// 결재선 그리드 데이터
            record 				  : me.getRecord(),
            docData               : {								 		// 결재문서 데이터
                fieldValues       : vm.get('fieldValues'),
                beforechange      : [],
                afterchange       : vm.get('docData.afterchange') 			 				// 결재문서 필드값
            }
        });
    },

    /* 초기화 */
    onContainerInitialize: function(component, eOpts) {
        var me = this,
            vm = me.getViewModel(),
            refs = me.getReferences(),
            approvalLineGrid = refs.approvalLineGrid, 	// 결재선
            afterchangeform = refs.detailForm,
            initialConfig = component.config, 			// 화면초기데이터
            aprHistId = initialConfig.aprHistId, 		// 결재내역ID
            command = initialConfig.command,
            aprHistData = initialConfig.aprHistData, 	// 결재이력데이터
            // 결재함(ExpNteApr02)에서는 docData,
            // 연수보고(HrdCrsInfo01)에서는 aprHistData.docData
            docData = (aprHistData) ? aprHistData.docData : initialConfig.docData, 				// 문서데이터
            afterchange = docData.afterchange,
            record = initialConfig.record, 				// 결재함 목록에서 선택한 레코드
            edocCd = 'HrdCrsInfo71',					// 문서코드
            edocNm = '연수취소신청서',
            userId = SecurityUtils.getPrincipal().hrHrpmEmpId, // 사용자ID
            grid = refs.detailGrid;

        vm.set('docCd', edocCd);
        vm.set('docNm', edocNm);
        vm.set('aprHistId', aprHistId);
        vm.set('record', record);
        vm.set('command', command);
        vm.set('docData', docData);

        me.setParentView(component.parentView);		// 부모 창
        me.setAprHistId(aprHistId); // 결재이력아이디
        me.setRecord(record); // 동시성 제어를 하기 위한 용도로 Config에 저장함
        me.setCommand(command); // 결재처리 커맨드

        // 결재문서 초기화 설정
        ApprovalBoxSvc.setup({
            command : command, 		// 결재선구분커맨드
            viewModel : vm,
            edocCd : edocCd, 		// 전자문서관리화면에 설정된 문서코드: 화면ID를 사용
            aprHistId : aprHistId, 	// 결재이력ID
            scope : me
        });

        var crudNm = '';
        switch(afterchange[0].crud) {
            case 'C' :
            crudNm = '신규';
            break;
            case 'U' :
            crudNm = '변경';
            break;
            case 'D' :
            crudNm = '삭제';
            break;
        }
        refs.crudNm.setValue(crudNm);		// 구분
        refs.stcdNm.setValue(CodeUtils.getText('INB014', afterchange[0].stcd));						// 상태
        refs.sttnAplStcdNm.setValue(CodeUtils.getText('HRD015', afterchange[0].sttnAplStcd));		// 신청상태
        refs.sttnEduDvcdNm.setValue(CodeUtils.getText('HRD005', afterchange[0].sttnEduDvcd));		// 연수교육구분
        refs.sttnAplDtHiphone.setValue(DateUtils.parseDate(afterchange[0].sttnAplDt).substr(0,10));		// 연수신청일자
        refs.sttnCmpYnNm.setValue(CodeUtils.getText('HRD021', afterchange[0].sttnCmpYn));			// 연수이수여부
        afterchange[0].sttnStrdtHiphone = DateUtils.parseDate(afterchange[0].sttnStrdt).substr(0,10);
        afterchange[0].sttnEdtHiphone = DateUtils.parseDate(afterchange[0].sttnEdt).substr(0,10);
        vm.set('detail', afterchange[0]);				// formData
        afterchangeform.setValues(vm.get('detail'));

        grid.el.select('.x-headercontainer').setStyle('height',	'0px');
        grid.setData(afterchange);						// gridData
    }

});